class Wallet {
  constructor(money) { this.money = money; }
  canBuy(price) { return this.money >= price; }
  buy(price) {
    if (this.canBuy(price)) {
      this.money -= price;
      return true;
    }
    return false;
  }
}
const w = new Wallet(10);
console.log(w.buy(6), w.buy(6), w.money);

