class Account {
  constructor(balance) {
    this.balance = balance;
  }
  deposit(amount) {
    if (amount > 0) {
      this.balance += amount;
    }
  }
  withdraw(amount) {
    if (amount <= this.balance) {
      this.balance -= amount;
    }
  }
}

function bankBalance(start, actions) {
  const account = new Account(start);
  for (const [type, amount] of actions) {
    if (type === "deposit") {
      account.deposit(amount);
    } else if (type === "withdraw") {
      account.withdraw(amount);
    }
  }
  return account.balance;
}
